    version: 1,
    fps,
    assets: [],
    tracks: [
      { id: "v1", kind: "video", name: "Video 1", muted: false, locked: false },
      { id: "m1", kind: "music", name: "Music 1", muted: false, locked: false },
    ],
    clips: [],
